// Pillar Pod Digital Gauges: Event History app for the BeamNG UI.
// GENERATED by tools/build_viewer.py from viewer/app.template.js and viewer/viewer.js; edit those.
//
// Shows the events the mod's recorder caught on the car you're driving. It asks the car's Lua for
// them (bngApi.activeObjectLua) and gets the answer as a "PillarPodRecorder" UI event.

/*@VIEWER@*/

angular.module('beamng.apps')
.directive('pillarPodEvents', ['$timeout', function ($timeout) {
  return {
    template: '<div style="width:100%; height:100%; pointer-events:auto;"></div>',
    replace: true,
    restrict: 'EA',
    scope: true,
    link: function (scope, element) {
      var REC = 'controller/gauges/customModules/dbgRecorder';
      function ask(what, arg) {
        var a = arg === undefined ? '' : ', ' + JSON.stringify(String(arg));
        bngApi.activeObjectLua('local r = package.loaded["' + REC + '"] if r and r.ui then r.ui("' + what + '"' + a + ') end');
      }

      // answers come back as UI events; each request waits for its kind, with a time limit
      var waiting = {summary: [], log: [], event: {}};
      function wait(list, ms) {
        return new Promise(function (resolve) {
          var done = false;
          var finish = function (v) { if (!done) { done = true; resolve(v); } };
          list.push(finish);
          setTimeout(function () { finish(null); }, ms);
        });
      }
      function flush(list, value) { var l = list.splice(0); l.forEach(function (f) { f(value); }); }

      // the game's unit settings (Options > Gameplay > Units)
      function gameUnits() {
        var u = (window.UiUnits && window.UiUnits.uiUnits) || {};
        var pr = u.uiUnitPressure;
        return {
          speed: u.uiUnitLength === 'imperial' ? 'imperial' : 'metric',
          temp: u.uiUnitTemperature === 'f' ? 'f' : 'c',
          pressure: pr === 'psi' || pr === 'inHg' ? 'psi' : pr === 'kPa' ? 'kPa' : 'bar'
        };
      }

      var source = {
        listEvents: function () {
          var p = wait(waiting.summary, 1500); ask('summary');
          return p.then(function (s) { return s || {status: 'norecorder'}; });
        },
        getEvent: function (id) {
          var list = waiting.event[id] = waiting.event[id] || [];
          var p = wait(list, 2000); ask('event', id);
          return p.then(function (r) { return r && r.event; });
        },
        getLog: function () {
          var p = wait(waiting.log, 2500); ask('log');
          return p;
        }
      };

      // the mod's own font, from its vehicle folder
      var FONT_DIR = '/vehicles/common/pillar_pod_gauges/fonts/barlow-semi-condensed-latin-';
      var fontCSS = [500, 600, 700].map(function (w) {
        return '@font-face{font-family:"Barlow SC";font-weight:' + w + ';src:url("' + FONT_DIR + w + '-normal.woff2") format("woff2");}';
      }).join('');

      var clearArmed = false, saveTimer = null;
      var viewer = window.PillarPodViewer.create(element[0], {
        source: source,
        live: true,
        units: gameUnits(),
        fontCSS: fontCSS,
        buttons: [
          {id: 'save', needsData: true, label: 'Save', title: 'Save this drive to pillar_pod_gauges/recordings in your BeamNG user folder', onClick: function (v, btn) {
            btn.textContent = 'Saving…'; btn.className = 'ppv-btn'; ask('save');
            clearTimeout(saveTimer);
            saveTimer = setTimeout(function () { btn.textContent = 'Save failed'; btn.className = 'ppv-btn warn'; }, 4000);
          }},
          {id: 'clear', needsData: true, label: 'Clear', title: 'Forget the events of this drive', onClick: function (v, btn) {
            if (!clearArmed) {
              clearArmed = true; btn.textContent = 'Clear all?'; btn.className = 'ppv-btn warn';
              setTimeout(function () { clearArmed = false; btn.textContent = 'Clear'; btn.className = 'ppv-btn'; }, 3000);
              return;
            }
            clearArmed = false; btn.textContent = 'Clear'; btn.className = 'ppv-btn'; ask('clear');
          }}
        ]
      });

      scope.$on('PillarPodRecorder', function (e, data) {
        if (!data) return;
        if (data.kind === 'summary') flush(waiting.summary, data);
        else if (data.kind === 'log') flush(waiting.log, data);
        else if (data.kind === 'event' && data.event) flush(waiting.event[data.event.id] || [], data);
        else if (data.kind === 'new') viewer.refresh();
        else if (data.kind === 'saved') {
          var btn = viewer.button('save');
          clearTimeout(saveTimer);
          if (btn) {
            btn.textContent = data.path ? 'Saved' : 'Save failed';
            btn.className = data.path ? 'ppv-btn ok' : 'ppv-btn warn';
            btn.title = data.path ? 'Saved to ' + data.path + ' in your BeamNG user folder' : 'The game could not write the file';
            saveTimer = setTimeout(function () { btn.textContent = 'Save'; btn.className = 'ppv-btn'; }, 5000);
          }
        }
      });
      scope.$on('SettingsChanged', function () { viewer.setUnits(gameUnits()); });

      // new events also arrive as pushes; this catches a change of car
      var poll = setInterval(function () { viewer.refresh(); }, 3000);
      var ro = window.ResizeObserver ? new ResizeObserver(function () { viewer.redraw(); }) : null;
      if (ro) ro.observe(element[0]);
      scope.$on('$destroy', function () { clearInterval(poll); if (ro) ro.disconnect(); });
    }
  };
}]);
